# AccountingLiveView Panel with Auto-Refresh

I'll create a new panel class that auto-refreshes journal entries and the corresponding backend endpoint.

## Backend Endpoint

First, let's add the backend endpoint for getting journal entries:

```csharp
app.AddEndpointWithBearerAuth<string>(
    "GetNJournalEntries",
    (AS, LoginInfo) =>
    {
        List<AccountsJournalEntry> AccJEList;
        using (var ctx = new NewinvContext())
        {
            AccJEList = ctx.AccountsJournalEntries.ToList();
        }
        return AccJEList;
    },
    "Refresh"
);
```

## AccountingLiveView Panel

Now, let's create the auto-refreshing panel:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using CommonUi;
using Eto.Forms;
using RV.InvNew.Common;

namespace EtoFE.Panels
{
    public class AccountingLiveView : Panel
    {
        private readonly int refreshIntervalSeconds = 30; // Configurable refresh interval
        private Timer refreshTimer;
        private GridView gridView;
        private StackLayout mainLayout;

        public AccountingLiveView()
        {
            InitializeUI();
            SetupRefreshTimer();

            // Initial data load
            RefreshData();
        }

        private void InitializeUI()
        {
            var LocalColor = ColorSettings.GetPanelSettings(
                "Editor",
                (IReadOnlyDictionary<string, object>)Program.ConfigDict
            );
            LocalColor = ColorSettings.RotateAllToPanelSettings(0);
            BackgroundColor = LocalColor?.BackgroundColor ?? ColorSettings.BackgroundColor;

            mainLayout = new StackLayout
            {
                Orientation = Orientation.Vertical,
                Padding = 10,
                Spacing = 5
            };

            // Add a header label
            var headerLabel = new Label
            {
                Text = TranslationHelper.Translate("Live Journal Entries View"),
                Font = new Font(ColorSettings.UIFont ?? SystemFonts.Default(), 12, FontStyle.Bold),
                TextColor = ColorSettings.ForegroundColor
            };

            // Add a status label
            var statusLabel = new Label
            {
                Text = TranslationHelper.Translate("Loading data..."),
                Font = new Font(ColorSettings.UIFont ?? SystemFonts.Default(), 10),
                TextColor = ColorSettings.LesserForegroundColor
            };

            mainLayout.Items.Add(new StackLayoutItem(headerLabel, HorizontalAlignment.Left));
            mainLayout.Items.Add(new StackLayoutItem(statusLabel, HorizontalAlignment.Left));

            Content = mainLayout;
        }

        private void SetupRefreshTimer()
        {
            refreshTimer = new Timer(TimerCallback, null, 
                TimeSpan.FromSeconds(refreshIntervalSeconds), 
                TimeSpan.FromSeconds(refreshIntervalSeconds));
        }

        private void TimerCallback(object state)
        {
            // This runs on a background thread
            RefreshData();
        }

        private void RefreshData()
        {
            // Start the data retrieval in a background thread
            Task.Run(() =>
            {
                try
                {
                    Log($"Fetching journal entries...");
                    var req = (
                        SendAuthenticatedRequest<string, List<AccountsJournalEntry>>.Send(
                            "Refresh",
                            "/GetNJournalEntries",
                            true
                        )
                    );

                    if (req.Error == false)
                    {
                        var JEs = req.Out;
                        Log($"Successfully retrieved {JEs.Count} journal entries");

                        // Update UI on the main thread
                        Application.Instance.Invoke(() =>
                        {
                            UpdateGrid(JEs);

                            // Update status
                            if (mainLayout.Items.Count > 1 && mainLayout.Items[1].Control is Label statusLabel)
                            {
                                statusLabel.Text = TranslationHelper.Translate($"Last updated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                            }
                        });
                    }
                    else
                    {
                        Log($"Error retrieving journal entries: {req.ErrorMessage}");

                        // Update UI on the main thread
                        Application.Instance.Invoke(() =>
                        {
                            if (mainLayout.Items.Count > 1 && mainLayout.Items[1].Control is Label statusLabel)
                            {
                                statusLabel.Text = TranslationHelper.Translate($"Error: {req.ErrorMessage}");
                            }
                        });
                    }
                }
                catch (Exception ex)
                {
                    Log($"Exception in RefreshData: {ex.Message}");

                    // Update UI on the main thread
                    Application.Instance.Invoke(() =>
                    {
                        if (mainLayout.Items.Count > 1 && mainLayout.Items[1].Control is Label statusLabel)
                        {
                            statusLabel.Text = TranslationHelper.Translate($"Exception: {ex.Message}");
                        }
                    });
                }
            });
        }

        private void UpdateGrid(List<AccountsJournalEntry> journalEntries)
        {
            // Create or update the grid view with the new data
            var newGrid = SearchPanelUtility.GenerateSearchPanel(
                journalEntries,
                false,
                null,
                [
                    "TimeAsEntered",
                    "DebitAccountName",
                    "CreditAccountName",
                    "Amount",
                    "JournalNo",
                    "PrincipalName",
                ]
            );

            // Replace the old grid if it exists, or add it for the first time
            if (gridView != null)
            {
                // Remove the old grid (assuming it's the third item in the stack layout)
                if (mainLayout.Items.Count > 2)
                {
                    mainLayout.Items.RemoveAt(2);
                }
            }

            // Add the new grid
            gridView = newGrid;
            mainLayout.Items.Add(new StackLayoutItem(newGrid, HorizontalAlignment.Stretch, true));

            Log($"Journal entries grid updated with {journalEntries.Count} entries");
        }

        private void Log(string message)
        {
            Console.WriteLine($"[AccountingLiveView] {message}");
        }

        protected override void OnDispose(bool disposing)
        {
            if (disposing)
            {
                // Clean up the timer
                refreshTimer?.Dispose();
            }
            base.OnDispose(disposing);
        }
    }
}
```

## Key Features

1. **Auto-Refresh**: The panel automatically refreshes every 30 seconds (configurable via `refreshIntervalSeconds`)

2. **Thread-Safe UI Updates**: Data retrieval happens in a background thread, but UI updates are marshaled to the main thread using `Application.Instance.Invoke()`

3. **Status Updates**: The panel shows when data was last updated or any errors that occurred

4. **Efficient Updates**: The grid is only updated when new data is successfully retrieved

5. **Resource Cleanup**: The timer is properly disposed when the panel is disposed

6. **Error Handling**: The panel handles exceptions and displays error messages to the user

7. **Logging**: All operations are logged to the console for debugging purposes

This implementation follows the same pattern as the existing `AllJournalEntries` panel but adds the auto-refresh functionality while ensuring thread safety.

